// friday13.cs — Friday the 13th experiments with the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
var earliest = Enumerable.Range(1, 12)
    .Select(m => new DateTime(1, m, 13))
    .First(d => d.DayOfWeek == DayOfWeek.Friday);

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest.DayOfWeek})");

// Count Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
var monthCounts = new Dictionary<int, int>();

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            monthCounts[month] = monthCounts.GetValueOrDefault(month) + 1;
        }
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

Console.WriteLine("\nBreakdown by month:");
foreach (var (month, n) in monthCounts.OrderByDescending(kv => kv.Value))
    Console.WriteLine($"  {new DateTime(1, month, 1):MMMM,-12} {n}");

// Distribution by day-of-week for the 13th
Console.WriteLine("\nHow often does the 13th fall on each day (400-year cycle)?");
var dayCounts = new int[7];
for (int year = 1; year <= 400; year++)
    for (int month = 1; month <= 12; month++)
        dayCounts[(int)new DateTime(year, month, 13).DayOfWeek]++;

foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-12} {dayCounts[(int)dow],4}  {(dow == DayOfWeek.Friday ? "<-- most common!" : "")}");

